-- keeping-user-api 목업 DB 스키마 (MySQL 8.0)
-- 원본 저장소에는 DDL 이 없다(synchronize: false). 엔티티 메타데이터에서 생성했다:
--   portfolio-notes/keeping-user-api/tools/gen-schema.js (TypeORM 0.2.45 Table.create + sqlInMemory)
-- 투영 엔티티(PublicUserProFile·FindFeedEntity·FindFeedPicture)는 같은 테이블의 주 엔티티로 대신한다.
-- @OneToOne 소유 측의 REL_ unique index 는 뺐다(작성자 관계 등이 실제로는 N:1). magazine_body_ko·en 은 1:1 이라 남겼다.
-- FK 는 엔티티의 onDelete 그대로 테이블 생성 뒤 ALTER TABLE 로 붙인다.
-- type 'timestamp' + default CURRENT_TIMESTAMP() 컬럼은 TypeORM 이 만드는 timestamp(6) 대신 timestamp 로 둔다(MySQL ER 1067).
-- PK 외 컬럼은 NULL 허용이다. 엔티티의 nullable 은 실제 DB 와 다르다(예: user.entity.ts:103 DeleteDateColumn → Column 변경 주석,
--   magazine.repository.ts:75 의 top_view_number IS NOT NULL 조건).
-- feed.state·magazine.state 의 DEFAULT '..._pending' 은 엔티티에 없고 코드에서 역추정했다(feed.service.ts:438-465, magazine.service.ts:161-172).
CREATE TABLE `admin-menu` (`id` varchar(36) NOT NULL, `menu_name` varchar(255) NULL, `parent_id` varchar(255) NULL, `url` varchar(255) NULL, `sort` int NULL, `depth` int NULL, `modified_at` datetime NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `admin_access_log` (`id` int NOT NULL AUTO_INCREMENT, `access_type` varchar(255) NULL, `access_location` varchar(255) NULL, `access_ip_address` varchar(255) NULL, `contents` varchar(255) NULL, `actions` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `admin_user` (`id` varchar(36) NOT NULL, `user_id` varchar(255) NULL, `code_authority_id` varchar(255) NULL, `user_name` varchar(255) NULL, `description_text` varchar(255) NULL, `modify_at` datetime NULL, `create_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `authority_menus` (`id` varchar(36) NOT NULL, `admin_menu_id` varchar(255) NULL, `code_authority_id` varchar(255) NULL, `modified_at` datetime NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `bbs_board` (`id` varchar(36) NOT NULL, `user_id` varchar(255) NULL, `category` varchar(255) NULL, `title` varchar(255) NULL, `content` varchar(255) NULL, `hit` int NULL, `attach_file_url1` varchar(255) NULL, `attach_file_url2` varchar(255) NULL, `attach_file_url3` varchar(255) NULL, `is_fixed` tinyint NULL, `event_name` varchar(255) NULL, `disabled` tinyint NULL, `created_at` datetime NULL, `modified_at` datetime NULL, `deleted_at` datetime NULL, `status` varchar(255) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `code_authority` (`id` varchar(36) NOT NULL, `role_code` varchar(255) NULL, `description_ko` varchar(255) NULL, `description_en` varchar(255) NULL, `priority` int NULL, `write_permission` tinyint NULL, `read_permission` tinyint NULL, `modify_permission` tinyint NULL, `delete_permission` tinyint NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `code_category` (`id` varchar(255) NOT NULL, `text_ko` varchar(255) NULL, `text_en` varchar(255) NULL, `sequence_number` int NULL, `select_yn` tinyint NULL, `created_by` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), `updated_by` varchar(255) NULL, `updated_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `code_item` (`id` varchar(255) NOT NULL, `code_category_id` varchar(255) NULL, `text_ko` varchar(255) NULL, `text_en` varchar(255) NULL, `sequence_number` int NULL, `select_yn` tinyint NULL, `created_by` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), `updated_by` varchar(255) NULL, `updated_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `feed` (`id` varchar(36) NOT NULL, `user_id` varchar(255) NULL, `state` varchar(255) NULL DEFAULT 'feed_state_pending', `content` varchar(255) NULL, `picture` varchar(255) NULL, `uploaded_at` datetime NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), `deleted_at` datetime(6) NULL, `updated_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), `sorted_at` datetime NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `feed_bookmark` (`id` varchar(36) NOT NULL, `feed_id` varchar(255) NULL, `user_id` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `feed_comment` (`id` varchar(36) NOT NULL, `feed_id` varchar(255) NULL, `user_id` varchar(255) NULL, `parent_id` varchar(255) NULL, `text` varchar(255) NULL, `deleted_at` datetime(6) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), `updated_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `feed_comment_like` (`id` varchar(36) NOT NULL, `feed_comment_id` varchar(255) NULL, `user_id` varchar(255) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `feed_comment_mention` (`id` varchar(36) NOT NULL, `feed_comment_id` varchar(255) NULL, `mention_user_id` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `feed_like` (`feed_id` varchar(255) NOT NULL, `user_id` varchar(255) NOT NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`feed_id`, `user_id`)) ENGINE=InnoDB;
CREATE TABLE `feed_picture` (`id` varchar(36) NOT NULL, `feed_id` varchar(255) NULL, `url` varchar(255) NOT NULL, `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`, `url`)) ENGINE=InnoDB;
CREATE TABLE `feed_tag` (`id` varchar(36) NOT NULL, `feed_id` varchar(255) NULL, `name` varchar(255) NULL, `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `feed_topic` (`id` varchar(36) NOT NULL, `feed_id` varchar(255) NULL, `topic_id` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `file` (`bucket` varchar(255) NOT NULL, `key` varchar(255) NOT NULL, `user_id` varchar(255) NULL, `url` varchar(255) NULL COMMENT 'S3 location url', `originalname` varchar(255) NULL, `encoding` varchar(255) NULL, `mimetype` varchar(255) NULL, `size` int NULL, `acl` varchar(255) NULL, `location` varchar(255) NULL, `etag` varchar(255) NULL, `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`bucket`, `key`)) ENGINE=InnoDB;
CREATE TABLE `file_tag` (`id` varchar(36) NOT NULL, `bucket` varchar(255) NULL, `key` varchar(255) NULL, `user_id` varchar(255) NULL, `name` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), `updated_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `follow` (`id` varchar(36) NOT NULL, `from_user` varchar(255) NULL, `to_user` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `magazine` (`id` varchar(36) NOT NULL, `user_id` varchar(255) NULL, `category` varchar(255) NULL, `state` varchar(255) NULL DEFAULT 'magazine_state_pending', `picture` varchar(255) NULL, `top_view_number` int NULL, `deleted_at` datetime(6) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), `updated_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `magazine_body_en` (`id` varchar(36) NOT NULL, `magazine_id` varchar(255) NULL, `title` varchar(255) NULL, `body` varchar(255) NULL, UNIQUE INDEX `REL_ac93278c92e1c0c4f2a2594725` (`magazine_id`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `magazine_body_ko` (`id` varchar(36) NOT NULL, `magazine_id` varchar(255) NULL, `title` varchar(255) NULL, `body` varchar(255) NULL, UNIQUE INDEX `REL_903589964a78be928156c9f147` (`magazine_id`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `magazine_bookmark` (`id` varchar(36) NOT NULL, `magazine_id` varchar(255) NULL, `user_id` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `magazine_comment` (`id` varchar(36) NOT NULL, `magazine_id` varchar(255) NULL, `user_id` varchar(255) NULL, `parent_id` varchar(255) NULL, `text` varchar(255) NULL, `deleted_at` datetime(6) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), `updated_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `magazine_like` (`id` varchar(36) NOT NULL, `magazine_id` varchar(255) NULL, `user_id` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `magazine_picture` (`id` varchar(36) NOT NULL, `magazine_id` varchar(255) NULL, `name` varchar(255) NULL, `url` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `magazine_tag` (`id` varchar(36) NOT NULL, `magazine_id` varchar(255) NULL, `name_ko` varchar(255) NULL, `name_en` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `magazine_topic` (`id` varchar(36) NOT NULL, `magazine_id` varchar(255) NULL, `topic_id` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `magazine_views` (`id` varchar(36) NOT NULL, `magazine_id` varchar(255) NULL, `user_id` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `topic_item` (`id` varchar(36) NOT NULL, `name_ko` varchar(255) NULL, `name_en` varchar(255) NULL, `url` varchar(255) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `user` (`id` varchar(36) NOT NULL, `provider` varchar(255) NULL, `provided_id` varchar(255) NULL, `password` varchar(255) NULL, `name` varchar(255) NULL, `nickname` varchar(255) NULL, `age` int NULL, `sex` varchar(255) NULL, `birth_date` varchar(255) NULL, `email` varchar(255) NULL, `email_verified` tinyint NULL, `email_verification_code` int NULL, `email_verification_code_expiresin` datetime NULL, `email_to_change` varchar(255) NULL, `phone_number` varchar(255) NULL, `phone_number_verified` tinyint NULL, `phone_number_verification_code` int NULL, `phone_number_verification_code_expiresin` datetime NULL, `phone_number_to_change` tinyint NULL, `reset_password_link_used` tinyint NULL, `color` varchar(255) NULL, `fcm_token` varchar(255) NULL, `about_me` varchar(255) NULL, `agreement_age` tinyint NULL, `agreement_privacy` tinyint NULL, `agreement_service_terms` tinyint NULL, `agreement_marketing` tinyint NULL, `deleted_at` datetime NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), `updated_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `user_background` (`id` varchar(36) NOT NULL, `user_id` varchar(255) NULL, `url` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `user_picture` (`id` varchar(36) NOT NULL, `user_id` varchar(255) NULL, `url` varchar(255) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `user_search` (`id` varchar(36) NOT NULL, `user_id` varchar(255) NULL, `text` varchar(255) NULL, `deleted_at` datetime(6) NULL, `created_at` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `user_withdrawal_temporary` (`id` varchar(36) NOT NULL, `user_id` varchar(255) NULL, `reason` varchar(255) NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
